1→/**
 * Cliente JSON-RPC de Ethereum.
 *
 * El endpoint es **configuración del entorno** (`ETH_RPC_URL`): no se fija en el código ni se
 * asume ningún servicio de terceros. La red única del proyecto es Sepolia, chainId 11155111
 * (spec/00-fundaciones/activos-y-par-de-trading.md §1): si el nodo configurado reporta otro
 * chainId, el servicio lo señala como estado degradado (`MISMATCH`) en el health-check y lo
 * registra, porque operar contra otra red violaría INV-6.
 */
10→import { CHAIN_ID } from '../config/index.js';

export type JsonRpcError = { code: number; message: string };

export class JsonRpcClient {
  private nextId = 1;

  constructor(
    private readonly url: string,
    private readonly timeoutMs = 5000,
20→  ) {}

  async call<T>(method: string, params: unknown[] = []): Promise<T> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.timeoutMs);
    try {
      const response = await fetch(this.url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', id: this.nextId++, method, params }),
30→        signal: controller.signal,
      });
      if (!response.ok) {
        throw new Error(`El nodo JSON-RPC respondió HTTP ${response.status}.`);
      }
      const body = (await response.json()) as { result?: T; error?: JsonRpcError };
      if (body.error !== undefined) {
        throw new Error(`Error JSON-RPC ${body.error.code}: ${body.error.message}`);
      }
      return body.result as T;
40→    } finally {
      clearTimeout(timer);
    }
  }

  /** `eth_chainId` devuelve el chainId en hexadecimal; se normaliza a string decimal. */
  async chainId(): Promise<string> {
    const hex = await this.call<string>('eth_chainId');
    return BigInt(hex).toString(10);
  }
50→
  /** Balance en wei de una dirección (entero exacto como string; nunca float). */
  async getBalanceWei(address: string, block = 'latest'): Promise<string> {
    const hex = await this.call<string>('eth_getBalance', [address, block]);
    return BigInt(hex).toString(10);
  }
}

export type ChainStatus =
  | { status: 'NOT_CONFIGURED' }
60→  | { status: 'OK'; chainId: string; checkedAt: string }
  | { status: 'MISMATCH'; chainId: string; expected: string; checkedAt: string }
  | { status: 'UNREACHABLE'; reason: string; checkedAt: string };

/** Sonda del nodo configurado; nunca lanza (el health-check no debe caerse por el nodo). */
export async function probeChain(client: JsonRpcClient | null): Promise<ChainStatus> {
  if (client === null) return { status: 'NOT_CONFIGURED' };
  const checkedAt = new Date().toISOString();
  try {
    const chainId = await client.chainId();
70→    if (chainId !== CHAIN_ID) {
      return { status: 'MISMATCH', chainId, expected: CHAIN_ID, checkedAt };
    }
    return { status: 'OK', chainId, checkedAt };
  } catch (error) {
    return {
      status: 'UNREACHABLE',
      reason: error instanceof Error ? error.message : 'error desconocido',
      checkedAt,
    };
80→  }
}

