blocks = [b for b in blocks if b.strip()]
print('n_blocks', len(blocks))
files = {}
hits = []
for b in blocks:
    first = b.splitlines()[0]
    m = re.match(r'(K-\d{3,4}) (\S+):(\d+)', first)
    if not m:
        print('BAD', first[:80])
        continue
    k, path, line = m.group(1), m.group(2), int(m.group(3))
    files.setdefault(path, []).append(k)
    # extract hit line (the one with >)
    hit = ''
    for ln in b.splitlines()[1:]:
        if '>' in ln[0:10] if len(ln)>10 else False or re.search(r'\d+>', ln):
            if '>' in ln:
                hit = ln.split('>',1)[-1].strip()
                break
    hits.append((k, path, line, hit, b))

print('n_files', len(files), 'parsed', len(hits))
# standard numbers
stds = {}
for k,path,line,hit,b in hits:
    for m in re.finditer(r'\b(BIP|EIP|ERC|SLIP)[-_ ]?(\d{1,4})\b', b, re.I):
        key = m.group(0).upper().replace('_','-').replace(' ','-')
        # normalize
        name = m.group(1).upper()
        num = m.group(2)
        key = f'{name}-{int(num)}'
        stds.setdefault(key, set()).add(k)

print('\n=== STANDARDS ===')
for s, ks in sorted(stds.items(), key=lambda x: (x[0].split('-')[0], int(x[0].split('-')[1]))):
    print(f'{s:12} {len(ks):4d}  first={min(ks)} last={max(ks)}')

# eth_ methods
eth = {}
for k,path,line,hit,b in hits:
    for m in re.finditer(r'\beth_[a-zA-Z]+', b):
        eth.setdefault(m.group(0), set()).add(k)
print('\n=== eth_ methods ===')
for s, ks in sorted(eth.items()):
    print(f'{s:30} {len(ks):4d}')

# chain ids
print('\n=== chainId-like numbers ===')
cids = {}
for k,path,line,hit,b in hits:
    for m in re.finditer(r'\b(1115511[0-9]|chainId[^\n]{0,40})', b, re.I):
        t = m.group(0)[:60]
        if '1115511' in t:
            cids.setdefault(t, set()).add(k)
for s, ks in sorted(cids.items(), key=lambda x: -len(x[1])):
    print(f'{s!r:40} {len(ks)}')
