      expect(toChecksumAddress(entrada)).toBe(esperado);
      // Acepta entrada con `0x`, en mayúsculas y ya con checksum aplicado (idempotente).
      expect(toChecksumAddress(`0x${entrada}`)).toBe(esperado);
      expect(toChecksumAddress(`0x${entrada.toUpperCase()}`)).toBe(esperado);
      expect(toChecksumAddress(esperado)).toBe(esperado);
      expect(isValidChecksumAddress(esperado)).toBe(true);
