1→/**
 * Envoltorio de las primitivas criptográficas de bajo nivel usadas por BIP-32.
 *
 * Se exporta como un **objeto mutable** (no como funciones sueltas) a propósito: el
 * escenario AT-06-02-08 de HU-06-02 exige que un test harness pueda inyectar un stub de
 * `HMAC-SHA512` para forzar la condición de borde `I_L >= n` o `k_hijo == 0` (RN-8), que
 * tiene probabilidad ~2⁻¹²⁷ y nunca se activa de forma natural.
 *
 * Contrato para el resto del módulo: el código de BIP-32 debe invocar SIEMPRE
10→ * `primitives.hmacSha512(...)` a través del objeto, y nunca capturar la función en una
 * constante local en tiempo de import; de lo contrario el stub no tendría efecto.
 */
import { hmac } from '@noble/hashes/hmac.js';
import { sha512 } from '@noble/hashes/sha2.js';

export type HmacSha512 = (key: Uint8Array, data: Uint8Array) => Uint8Array;

export const primitives: { hmacSha512: HmacSha512 } = {
  /** HMAC-SHA512 (RFC 4231), la PRF de BIP-32 (HU-06-02 RN-1 y RN-3). */
20→  hmacSha512(key: Uint8Array, data: Uint8Array): Uint8Array {
    return hmac(sha512, key, data);
  },
};

