1→/**
 * Configuración del servicio.
 *
 * Todo lo que depende del entorno (puerto, base de datos, endpoint JSON-RPC, credencial de
 * cifrado del seed, dirección del contrato USDC-mock, TTL de sesión) se lee de variables de
 * entorno. Los valores que la spec fija como constantes del proyecto (chainId, red,
 * confirmaciones requeridas, umbrales de rate limiting) NO son configurables.
 *
 * Fuentes: spec/00-fundaciones/activos-y-par-de-trading.md §1,
10→ * spec/01-cuentas-y-autenticacion/HU-01-02 RN-3 (rango del TTL),
 * spec/06-wallet-hd-y-direcciones/HU-06-01 RN-6 (credencial de cifrado por entorno).
 */
import { AppError } from '../shared/errors.js';
import { toChecksumAddress } from '../wallet/crypto/address.js';

/** Constantes fijadas por la spec (no configurables). */
export const CHAIN_ID = '11155111' as const;
export const NETWORK_NAME = 'sepolia' as const;
export const COIN_TYPE = 60 as const;
20→export const REQUIRED_CONFIRMATIONS = 12 as const;
export const SUPPORTED_ASSETS = ['ETH', 'USDC'] as const;
export type Asset = (typeof SUPPORTED_ASSETS)[number];

/** Rate limiting público por origen (HU-01-01 RN-10, HU-01-02 RN-9). */
export const PUBLIC_RATE_LIMIT_MAX = 60;
export const PUBLIC_RATE_LIMIT_WINDOW_MS = 60_000;
/** Rate limiting por cuenta autenticada y por endpoint (HU-09-02 RN-12). */
export const ACCOUNT_RATE_LIMIT_MAX = 60;
export const ACCOUNT_RATE_LIMIT_WINDOW_MS = 60_000;
30→
/** Política de contraseña (HU-01-01 RN-3). */
export const PASSWORD_MIN_LENGTH = 8;
export const PASSWORD_MAX_LENGTH = 128;
/** Longitud máxima del email (HU-01-01 RN-2). */
export const EMAIL_MAX_LENGTH = 254;

export const SESSION_TTL_MIN_SECONDS = 60;
export const SESSION_TTL_MAX_SECONDS = 86_400;
export const SESSION_TTL_DEFAULT_SECONDS = 3600;
40→
export type Config = {
  host: string;
  port: number;
  databasePath: string;
  sessionTtlSeconds: number;
  wallet: {
    /**
     * Clave AES-256-GCM del seed, o `null` si la variable falta o no decodifica a 32 bytes.
     * La ausencia/invalidez NO se trata como error de configuración del arranque: la spec la
50→     * equipara a un fallo de descifrado (HU-06-01 RN-6), que el provisioning resuelve con
     * `INTERNAL_ERROR` cuando ya hay un seed persistido.
     */
    encryptionKey: Buffer | null;
    /** Motivo por el que no hay una clave utilizable (para el mensaje de aborto). */
    encryptionKeyIssue: string | null;
    /** Mnemonic importado por configuración (opcional). Si falta, se genera uno nuevo. */
    mnemonic: string | undefined;
    passphrase: string;
  };
60→  chain: {
    rpcUrl: string | undefined;
    chainId: string;
    network: string;
    usdcContractAddress: string;
  };
  internalApiKey: string | undefined;
  /**
   * Orígenes HTTP autorizados a llamar la API desde un navegador, o `null` si CORS está
   * **deshabilitado** (variable `CORS_ALLOWED_ORIGINS` ausente o vacía).
70→   *
   * No es un requisito de la spec: la superficie REST (HU-09-01) y su autenticación
   * (HU-09-02) no dependen del navegador. Es configuración operativa para que el cliente web
   * de la épica 10 pueda correr en otro origen (p. ej. el dev server en
   * `http://localhost:5173`). Apagado por defecto: sin la variable, el servidor responde
   * exactamente igual que antes de existir esta opción (ningún header extra).
   */
  corsAllowedOrigins: string[] | null;
  logLevel: string;
};
80→
/** Error de configuración: impide el arranque del servicio (no se inicia en estado inválido). */
export class ConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ConfigError';
  }
}

function parseIntegerEnv(name: string, raw: string | undefined, fallback: number): number {
90→  if (raw === undefined || raw.trim() === '') return fallback;
  if (!/^-?\d+$/.test(raw.trim())) {
    throw new ConfigError(`${name} debe ser un entero; se recibió "${raw}".`);
  }
  return Number.parseInt(raw.trim(), 10);
}

/**
 * Decodifica la clave de cifrado del seed: 32 bytes exactos, en hex (64 chars) o base64
 * (HU-06-01 RN-6: AES-256-GCM con clave de 256 bits provista por el entorno).
100→ *
 * No lanza: una clave ausente o mal formada es, a los ojos de la spec, una **credencial
 * ausente/incorrecta**, y su tratamiento (abortar con `INTERNAL_ERROR` al no poder descifrar
 * un seed ya persistido) corresponde al provisioning, no a la validación de configuración.
 */
function parseEncryptionKey(raw: string | undefined): { key: Buffer | null; issue: string | null } {
  if (raw === undefined || raw.trim() === '') {
    return {
      key: null,
      issue:
110→        'WALLET_ENCRYPTION_KEY ausente: se espera una clave de 32 bytes en hex (64 caracteres) o base64. ' +
        'La credencial de cifrado del seed se provee por configuración del entorno y nunca se ' +
        'persiste junto al material cifrado (HU-06-01 RN-6).',
    };
  }
  const value = raw.trim();

  // Hex: 32 bytes exactos (64 dígitos), con o sin prefijo `0x`.
  if (/^(0x)?[0-9a-fA-F]{64}$/u.test(value)) {
    return { key: Buffer.from(value.replace(/^0x/u, ''), 'hex'), issue: null };
120→  }

  // Base64 estándar de 32 bytes: 43 caracteres del alfabeto + padding opcional. Se valida
  // de forma **estricta** y con round-trip, porque `Buffer.from(v, 'base64')` descarta en
  // silencio los caracteres inválidos y aceptaría como clave de 256 bits una cadena mal
  // tipeada. Así el diagnóstico "credencial incorrecta" (RN-6) no se confunde con
  // "credencial mal formada pero aceptada".
  if (/^[A-Za-z0-9+/]{43}=?$/u.test(value)) {
    const key = Buffer.from(value, 'base64');
    if (key.length === 32 && key.toString('base64') === `${value.replace(/=$/u, '')}=`) {
130→      return { key, issue: null };
    }
    return {
      key: null,
      issue:
        'WALLET_ENCRYPTION_KEY no es un base64 canónico de 32 bytes (los bits de relleno del ' +
        'último carácter deben ser cero).',
    };
  }

140→  return {
    key: null,
    issue:
      'WALLET_ENCRYPTION_KEY debe ser una clave de 32 bytes (256 bits) codificada en hex ' +
      '(64 dígitos, con o sin prefijo 0x) o en base64 estándar (43 caracteres + padding). ' +
      `El valor recibido tiene ${value.length} caracteres y no encaja en ninguno de los dos formatos.`,
  };
}

/**
150→ * Dirección Ethereum **obligatoria** de configuración, normalizada a checksum EIP-55.
 *
 * `00-fundaciones/activos-y-par-de-trading.md` §2.2 define la dirección del USDC-mock como
 * parámetro del despliegue ("no se fija un valor literal aquí porque depende del despliegue
 * concreto… es única y constante por entorno"): no puede tener un valor por defecto, porque
 * un entorno sin configurar respondería en silencio con una dirección que no es la de su
 * USDC-mock. Su ausencia es un error de configuración que impide el arranque.
 *
 * HU-09-01 RN-10 y HU-06-04 RN-6 exigen que `tokenAddress` viaje con checksum EIP-55, así
 * que el valor se normaliza acá una sola vez. Si la entrada es mixed-case, su capitalización
160→ * **es** un checksum: si no verifica, se rechaza (probablemente hay un dígito equivocado).
 */
function parseRequiredAddressEnv(name: string, raw: string | undefined): string {
  const value = raw?.trim() ?? '';
  if (value === '') {
    throw new ConfigError(
      `${name} es obligatoria y no está configurada. La dirección del contrato USDC-mock es un ` +
        'parámetro del despliegue (activos-y-par-de-trading.md §2.2): única y constante por ' +
        'entorno, sin valor por defecto.',
    );
170→  }
  if (!/^0x[0-9a-fA-F]{40}$/u.test(value)) {
    throw new ConfigError(`${name} debe ser una dirección Ethereum (0x + 40 hex); se recibió "${value}".`);
  }
  const body = value.slice(2);
  const carriesChecksum = body !== body.toLowerCase() && body !== body.toUpperCase();
  const checksummed = toChecksumAddress(value);
  if (carriesChecksum && value !== checksummed) {
    throw new ConfigError(
      `${name} está en mixed-case pero su checksum EIP-55 no verifica: se esperaba ` +
180→        `"${checksummed}" y se recibió "${value}".`,
    );
  }
  return checksummed;
}

/**
 * Lista de orígenes permitidos para CORS (`CORS_ALLOWED_ORIGINS`, separados por coma).
 *
 * Devuelve `null` —CORS deshabilitado— si la variable falta o queda vacía tras el trim: la
190→ * ausencia de configuración no puede cambiar en nada el comportamiento observable del
 * servidor. No se admite `*`: la API se consume con `Authorization: Bearer` y la respuesta
 * siempre hace eco del origen concreto, nunca un comodín.
 */
function parseCorsAllowedOrigins(raw: string | undefined): string[] | null {
  const value = raw?.trim() ?? '';
  if (value === '') return null;
  const origins = value
    .split(',')
    .map((origin) => origin.trim())
200→    .filter((origin) => origin !== '');

