1→/**
 * Provisioning y custodia del seed de la wallet HD (HU-06-01).
 *
 * - RN-1/RN-2: el mnemonic es BIP-39 de **24 palabras** (256 bits de entropía de CSPRNG),
 *   validado en orden longitud → wordlist → checksum, con normalización NFKD.
 * - RN-3: la seed binaria de 64 bytes se deriva con PBKDF2-HMAC-SHA512(2048).
 * - RN-4: hay **un solo** seed para todo el exchange.
 * - RN-6: se persiste cifrado en reposo con AES-256-GCM (nonce aleatorio de 96 bits por
 *   operación, tag de 128 bits), formato `nonce || ciphertext || tag`. La clave viene del
10→ *   entorno y nunca se persiste junto al material cifrado.
 * - RN-8/RN-9: no se regenera nunca; la escritura es atómica (transacción SQLite).
 * - RN-10/RN-11: al arrancar con mapeo no vacío se verifica que el seed derive la dirección
 *   persistida del índice más bajo; ante cualquier fallo crítico se **aborta sin regenerar**.
 *
 * El proceso de provisioning **no** es un endpoint HTTP: ante error lanza
 * `SeedProvisioningError`, que `main.ts` traduce en salida con código distinto de cero y el
 * `code` del catálogo en `stderr`, sin filtrar material secreto (RN-5).
 */
import { createCipheriv, createDecipheriv, randomBytes } from 'node:crypto';
20→import type { Db } from '../infra/db.js';
import { nowIso } from '../shared/time.js';
import { generateMnemonic, mnemonicToSeed, normalizeMnemonic, validateMnemonic } from './crypto/bip39.js';
import { deriveAccountAt } from './crypto/derivation.js';

const NONCE_BYTES = 12; // 96 bits (recomendado por NIST para GCM)
const TAG_BYTES = 16; // 128 bits

/** Error crítico de provisioning: el `code` pertenece al catálogo de 00-fundaciones. */
export class SeedProvisioningError extends Error {
30→  constructor(
    readonly code: 'VALIDATION_ERROR' | 'INTERNAL_ERROR',
    message: string,
  ) {
    super(message);
    this.name = 'SeedProvisioningError';
  }
}

export function encryptSecret(plaintext: string, key: Buffer): Buffer {
40→  const nonce = randomBytes(NONCE_BYTES);
  const cipher = createCipheriv('aes-256-gcm', key, nonce);
  const ciphertext = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  return Buffer.concat([nonce, ciphertext, cipher.getAuthTag()]);
}

export function decryptSecret(payload: Buffer, key: Buffer): string {
  if (payload.length < NONCE_BYTES + TAG_BYTES + 1) {
    throw new SeedProvisioningError('INTERNAL_ERROR', 'El material cifrado del seed está truncado.');
  }
50→  const nonce = payload.subarray(0, NONCE_BYTES);
  const tag = payload.subarray(payload.length - TAG_BYTES);
  const ciphertext = payload.subarray(NONCE_BYTES, payload.length - TAG_BYTES);
  const decipher = createDecipheriv('aes-256-gcm', key, nonce);
  decipher.setAuthTag(tag);
  try {
    return Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString('utf8');
  } catch {
    // El tag GCM no verifica: material corrupto o credencial incorrecta/ausente.
    throw new SeedProvisioningError(
60→      'INTERNAL_ERROR',
      'No se pudo descifrar el seed de la wallet HD (tag GCM inválido o credencial incorrecta). ' +
        'El sistema aborta sin regenerar ni sobrescribir el seed existente.',
    );
  }
}

export type WalletSeed = {
  /** Seed binaria BIP-39 de 64 bytes. Nunca se serializa ni se logea. */
  readonly seed: Uint8Array;
70→  /** `true` si el seed se generó en este arranque (no existía previamente). */
  readonly generated: boolean;
};

export type SeedStoreOptions = {
  /** Clave AES-256-GCM del seed, o `null` si la credencial está ausente o es inválida. */
  encryptionKey: Buffer | null;
  /** Motivo por el que no hay clave utilizable (se refleja en el mensaje de aborto). */
  encryptionKeyIssue?: string | null;
  /** Mnemonic importado por configuración; si falta y no hay seed, se genera uno nuevo. */
80→  mnemonic?: string | undefined;

