import { AppError } from '../shared/errors.js';
import { CHAIN_ID, NETWORK_NAME } from '../config/index.js';
import type { Db } from '../infra/db.js';
import { nowIso } from '../shared/time.js';
import { deriveNextValidAccount } from './crypto/derivation.js';
import type { DomainEventBus } from './events.js';

export type DepositAddressRecord = {
  accountId: string;
  addressIndex: number;
  address: string;
  derivationPath: string;
  network: string;
  chainId: string;
  createdAt: string;
};

export class DepositAddressService {
  constructor(
    private readonly db: Db,
    private readonly seed: Uint8Array,
    private readonly events: DomainEventBus,
  ) {}

  findByAccount(accountId: string): DepositAddressRecord | null {
    const row = this.db
      .prepare(
        `SELECT account_id AS accountId, address_index AS addressIndex, address,
                derivation_path AS derivationPath, network, chain_id AS chainId,
                created_at AS createdAt
         FROM deposit_addresses WHERE account_id = ?`,
      )
      .get(accountId) as DepositAddressRecord | undefined;
    return row ?? null;
  }

  list(): DepositAddressRecord[] {
    return this.db
      .prepare(
        `SELECT account_id AS accountId, address_index AS addressIndex, address,
                derivation_path AS derivationPath, network, chain_id AS chainId,
                created_at AS createdAt
         FROM deposit_addresses ORDER BY address_index ASC`,
      )
      .all() as DepositAddressRecord[];
  }

