   * insertando en la misma transacción.
   */
  assign(accountId: string, options: { checkAccountExists?: boolean } = {}): DepositAddressRecord {
    const checkAccountExists = options.checkAccountExists ?? true;
    const assignTx = this.db.transaction((): { record: DepositAddressRecord; created: boolean } => {
      if (checkAccountExists) {
        const account = this.db
          .prepare('SELECT account_id FROM accounts WHERE account_id = ?')
          .get(accountId) as { account_id: string } | undefined;
