cd sut/backend && npm install --ignore-scripts --no-audit --no-fund --silent && node --experimental-strip-types --input-type=module -e "
import { mnemonicToSeed } from './src/wallet/crypto/bip39.ts';
import { deriveAccountAt } from './src/wallet/crypto/derivation.ts';
const m = 'abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about';
for (const pass of ['', 'TREZOR']) {
  const seed = mnemonicToSeed(m, pass);
  const a0 = deriveAccountAt(seed, 0);
  console.log(JSON.stringify({pass, address: a0.address, path: a0.derivationPath}));
}
const hard = mnemonicToSeed('test test test test test test test test test test test junk', '');
console.log('hardhat', deriveAccountAt(hard, 0).address);
"

